package org.apache.commons.jxpath.util;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

import java.util.Arrays;
import java.util.Collection;
import java.util.List;

import org.junit.Test;

public class ConvertTests {

    private final BasicTypeConverter converter = new BasicTypeConverter();

    @Test
    public void testArrayToCollectionConversionProducesUnmodifiableCollection() {
        String[] source = new String[] {"a", "b"};

        Collection<?> result =
                (Collection<?>) converter.convert(source, List.class);

        assertEquals(Arrays.asList("a", "b"), result);

        try {
            result.clear();
            fail("Expected an unmodifiable collection");
        } catch (UnsupportedOperationException expected) {
            // Expected.
        }
    }
}

